using System.IO;
using System.Text;
using System.Text.Json;
using System.Text.RegularExpressions;

namespace DiscImageStudio.Localization;

/// <summary>Display-time translation for text produced by the engine libraries (burner,
/// project store, presets). Those libraries write their status, diagnostics and errors in
/// Chinese without going through <see cref="L"/>, and their tests assert that wording, so
/// this fork translates the text where the app shows it (job log, toasts, burn status)
/// instead of editing the libraries. Rules are generated by tools/build_library_text.py.
/// Off until <see cref="Enabled"/> is set by the real application host, so test hosts keep
/// the original text; it never runs while the UI language is Chinese.</summary>
public static class LibraryText
{
    private const string ResourceName = "DiscImageStudio.Localization.LibraryText.en.json";

    private static readonly Regex HolePattern = new(@"\{(\d+)(?:[,:][^{}]*)?\}", RegexOptions.CultureInvariant);

    private static readonly Regex CjkPattern = new(@"[㐀-鿿　-〿＀-￯]",
        RegexOptions.CultureInvariant);

    private static readonly Lazy<IReadOnlyList<Rule>> Rules = new(LoadRules);

    /// <summary>Set by the application host at startup.</summary>
    public static bool Enabled { get; set; }

    /// <summary>Returns <paramref name="text"/> with every known engine phrase replaced by
    /// English. Text without Chinese characters is returned unchanged.</summary>
    public static string Translate(string? text)
    {
        if (string.IsNullOrEmpty(text)) return text ?? string.Empty;
        if (!Enabled || L.CurrentLanguage is L.Chinese or L.TraditionalChinese) return text;
        if (!CjkPattern.IsMatch(text)) return text;

        string result = text;
        foreach (Rule rule in Rules.Value)
        {
            if (!result.Contains(rule.Anchor, StringComparison.Ordinal)) continue;
            result = rule.Pattern is null
                ? result.Replace(rule.Anchor, rule.English, StringComparison.Ordinal)
                : rule.Pattern.Replace(result, match => Expand(rule.English, match));
            if (!CjkPattern.IsMatch(result)) break;
        }

        return NormalizePunctuation(result);
    }

    private static string Expand(string english, Match match)
        => HolePattern.Replace(english, hole =>
        {
            Group group = match.Groups["h" + hole.Groups[1].Value];
            return group.Success ? group.Value : hole.Value;
        });

    /// <summary>Full-width separators left between translated fragments read oddly in
    /// English, so they become their ASCII forms.</summary>
    private static string NormalizePunctuation(string text)
    {
        StringBuilder builder = new(text.Length + 16);
        for (int index = 0; index < text.Length; index++)
        {
            char c = text[index];
            bool followedByText = index + 1 < text.Length && !char.IsWhiteSpace(text[index + 1]);
            switch (c)
            {
                case '；': builder.Append(followedByText ? "; " : ";"); break;
                case '：': builder.Append(followedByText ? ": " : ":"); break;
                case '，': builder.Append(followedByText ? ", " : ","); break;
                case '、': builder.Append(followedByText ? ", " : ","); break;
                case '。': builder.Append(followedByText ? ". " : "."); break;
                case '（': builder.Append(index > 0 && !char.IsWhiteSpace(text[index - 1]) ? " (" : "("); break;
                case '）': builder.Append(')'); break;
                case '“' or '”': builder.Append('"'); break;
                case '‘' or '’': builder.Append('\''); break;
                default: builder.Append(c); break;
            }
        }

        return builder.ToString();
    }

    private static IReadOnlyList<Rule> LoadRules()
    {
        using Stream? stream = typeof(LibraryText).Assembly.GetManifestResourceStream(ResourceName);
        if (stream is null) return [];
        List<RuleText>? entries = JsonSerializer.Deserialize<List<RuleText>>(stream,
            new JsonSerializerOptions { PropertyNameCaseInsensitive = true });
        List<Rule> rules = new(entries?.Count ?? 0);
        foreach (RuleText entry in entries ?? [])
        {
            if (string.IsNullOrEmpty(entry.Zh) || string.IsNullOrEmpty(entry.En)) continue;
            Rule? rule = Compile(entry.Zh, entry.En);
            if (rule is not null) rules.Add(rule);
        }

        return rules;
    }

    private static Rule? Compile(string chinese, string english)
    {
        MatchCollection holes = HolePattern.Matches(chinese);
        if (holes.Count == 0) return new Rule(chinese, null, english);

        StringBuilder pattern = new();
        HashSet<string> seen = new(StringComparer.Ordinal);
        string anchor = string.Empty;
        int position = 0;
        for (int index = 0; index < holes.Count; index++)
        {
            Match hole = holes[index];
            string literal = chinese[position..hole.Index];
            if (literal.Length > anchor.Length) anchor = literal;
            pattern.Append(Regex.Escape(literal));
            string name = "h" + hole.Groups[1].Value;
            bool first = index == 0 && hole.Index == 0;
            bool last = hole.Index + hole.Length == chinese.Length;
            if (!seen.Add(name)) pattern.Append(@"\k<").Append(name).Append('>');
            else if (first) pattern.Append("(?<").Append(name).Append(@">[^\s；。，：]+)");
            else if (last) pattern.Append("(?<").Append(name).Append(@">[^\n；。，]*)");
            else pattern.Append("(?<").Append(name).Append(">.*?)");
            position = hole.Index + hole.Length;
        }

        string tail = chinese[position..];
        if (tail.Length > anchor.Length) anchor = tail;
        pattern.Append(Regex.Escape(tail));
        // A rule made only of holes would match anything; it has no phrase to translate.
        if (anchor.Trim().Length == 0 || !CjkPattern.IsMatch(chinese)) return null;
        return new Rule(anchor, new Regex(pattern.ToString(), RegexOptions.CultureInvariant), english);
    }

    private sealed record RuleText(string Zh, string En);

    private sealed record Rule(string Anchor, Regex? Pattern, string English);
}
